21	
22	\begin{knowledgebox}{强大来源}
23	\begin{itemize}
24	    \item 反馈闭环缩短：用户不需等待人工产品迭代；
25	    \item 局部优化可积累：系统逐步贴合个人工作流；
26	    \item 复用性增强：修过一次的流程可迁移到相似任务。
27	\end{itemize}
28	\end{knowledgebox}
